begin;
do $$
declare u uuid; emp bigint; cust bigint; cust2 bigint; svc bigint; team bigint; member bigint;
 req jsonb; r jsonb; retry jsonb; template bigint; bigger bigint; contract bigint; booking bigint; denied boolean;
begin
 select id into u from public.profiles where role='staff' and lower(email)='cryomongolia@gmail.com';
 select id into emp from public.staff where active order by id limit 1;
 select id into cust from public.customers order by id limit 1;
 select id into cust2 from public.customers where id<>cust order by id limit 1;
 select id into svc from public.services where active and category<>'legacy-import' order by id limit 1;
 select id into team from public.sports_teams where archived_at is null order by id limit 1;
 if u is null or emp is null or cust is null or cust2 is null or svc is null or team is null then raise exception 'QA fixtures unavailable'; end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 execute 'set local role authenticated';
 req:=jsonb_build_object('action','template','request_id',gen_random_uuid(),'staff_id',emp,'package_name','QA rollback only','items',jsonb_build_array(jsonb_build_object('service_id',svc,'units',3)),'base_price',100000,'discount_percent',10);
 r:=public.package_checkout(req);template:=(r#>>'{package,id}')::bigint;
 if (r#>>'{package,price}')::bigint<>90000 then raise exception 'Template price failed'; end if;
 retry:=public.package_checkout(req);if retry<>r then raise exception 'Template retry not idempotent'; end if;
 req:=req||jsonb_build_object('request_id',gen_random_uuid(),'package_name','QA larger','base_price',200000,'discount_percent',0);
 r:=public.package_checkout(req);bigger:=(r#>>'{package,id}')::bigint;
 req:=jsonb_build_object('action','sell','request_id',gen_random_uuid(),'staff_id',emp,'customer_id',cust,'package_id',template,'amount',30000,'payment_method','cash');
 r:=public.package_checkout(req);contract:=(r#>>'{contract,id}')::bigint;
 if (r#>>'{sale,total}')::bigint<>30000 or (r#>>'{contract,agreed_price}')::bigint<>90000 then raise exception 'Partial payment failed'; end if;
 retry:=public.package_checkout(req);if retry<>r then raise exception 'Sale retry failed'; end if;
 denied:=false;begin perform public.package_checkout(jsonb_build_object('action','pay','request_id',gen_random_uuid(),'staff_id',emp,'contract_id',contract,'amount',60001,'payment_method','cash'));exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'Overpayment accepted';end if;
 req:=jsonb_build_object('action','pay','request_id',gen_random_uuid(),'staff_id',emp,'contract_id',contract,'amount',60000,'payment_method','internal');
 r:=public.package_checkout(req);
 if (r#>>'{sale,total}')::bigint<>0 or (r#>>'{sale,internal_amount}')::bigint<>60000 then raise exception 'Internal usage counted as revenue';end if;
 retry:=public.package_checkout(req);if retry<>r then raise exception 'Payment retry failed';end if;
 insert into public.package_redemptions(contract_id,used_on,units,service_id,service_label,staff_id) values(contract,current_date,1,svc,'QA',emp);
 r:=public.package_checkout(jsonb_build_object('action','change','request_id',gen_random_uuid(),'staff_id',emp,'contract_id',contract,'package_id',bigger));
 if (r->>'balance')::bigint<>110000 or (select sum(units) from public.package_redemptions where contract_id=contract)<>1 then raise exception 'Upgrade lost balance/history';end if;
 r:=public.package_checkout(jsonb_build_object('action','transfer','request_id',gen_random_uuid(),'staff_id',emp,'contract_id',contract,'customer_id',cust2,'note','QA rollback transfer'));
 if (r#>>'{contract,customer_id}')::bigint<>cust2 then raise exception 'Transfer failed'; end if;
 select id into member from public.add_sports_member(team,'QA rollback member');
 if member is null or member<>(select id from public.add_sports_member(team,'QA rollback member')) then raise exception 'Member retry failed';end if;
 insert into public.bookings(ref,customer_name,service_id,starts_at,status,staff_id) values('QA-'||gen_random_uuid(),'QA internal',svc,'2099-12-04 10:00+08','pending',emp) returning id into booking;
 r:=public.pay_booking(booking,jsonb_build_object('staff_id',emp,'customer_name','QA internal','services','QA','internal_amount',50000));
 if (r#>>'{sale,total}')::bigint<>0 or (r#>>'{sale,internal_amount}')::bigint<>50000 or r#>>'{booking,payment_status}'<>'paid' then raise exception 'Internal booking failed';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 denied:=false;begin perform public.package_checkout(req);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Nonemployee gained access'; end if;
end $$;
rollback;
select 'PASS: templates, partial payments, idempotency, overpayment, internal accounting, upgrade, transfer, members, roles. All QA records rolled back.' result;
